<style>
.ca50-inner-page{padding-bottom:64px;background:linear-gradient(180deg,#edf9ff,#fff);color:#203548}.ca50-inner-container{width:min(1240px,calc(100% - 48px));margin:auto}
.ca50-inner-breadcrumb{display:flex;flex-wrap:wrap;gap:12px;padding:24px 0;font-size:12px;color:#607c90}.ca50-inner-heading{padding:14px 0 32px;max-width:820px}.ca50-inner-heading h1{font-size:36px;line-height:1.35;margin:0 0 16px}.ca50-inner-heading p{font-size:15px;line-height:1.9;color:#60788a;margin:0}
.ca50-catalog-filters{display:grid;grid-template-columns:1.4fr 1fr 1fr auto;gap:18px;align-items:end;padding:24px;background:white;border:1px solid #dcecf5;border-radius:18px}.ca50-catalog-filters>div{min-width:0}.ca50-catalog-filters label{display:block;font-size:12px;font-weight:600;margin-bottom:10px}.ca50-catalog-filters input,.ca50-catalog-filters select{width:100%;min-width:0;min-height:46px;padding:12px;border:1px solid #ccdee9;border-radius:10px;background:#fbfdff;color:#203548;font:13px 'Be Vietnam Pro',sans-serif}
.ca50-inner-page .ca50-inner-button{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:46px;padding:12px 20px;border:0;border-radius:12px;background:var(--ca-blue);color:#fff;font:600 13px 'Be Vietnam Pro',sans-serif;cursor:pointer;white-space:nowrap}.ca50-inner-page .ca50-inner-button:hover{background:var(--ca-deep)}
.ca50-results-meta{display:flex;justify-content:space-between;gap:15px;font-size:13px;padding:24px 0;color:#60788a}.ca50-results-meta a{color:var(--ca-deep)}
.ca50-catalog-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px}.ca50-inner-page .ca50-product-card{text-align:left;background:#fff;border:1px solid #dcecf5;border-radius:18px}.ca50-inner-page .ca50-product-image{display:block;height:235px;background:#f1f8fc}.ca50-inner-page .ca50-product-image img{object-fit:contain}.ca50-inner-page .ca50-product-card h3{font-size:15px;line-height:1.6;min-height:0;font-weight:600}.ca50-inner-page .ca50-product-card strong{font-size:18px}
.ca50-service-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px}.ca50-service-card{background:#fff;border:1px solid #dcecf5;border-radius:20px;overflow:hidden;display:flex;flex-direction:column}.ca50-service-image{display:grid;place-items:center;height:240px;background:#def2fe;color:var(--ca-blue);font-size:48px}.ca50-service-image img{width:100%;height:100%;object-fit:cover}.ca50-service-card>div{padding:24px;display:flex;flex-direction:column;flex:1}.ca50-service-card h2{font-size:20px;line-height:1.5;margin:0 0 14px}.ca50-service-card p{font-size:14px;line-height:1.8;color:#60788a;margin:0 0 20px}.ca50-service-link{margin-top:auto;font-size:13px;font-weight:600;color:var(--ca-deep)!important}
.ca50-empty{grid-column:1/-1;text-align:center;padding:60px 24px;background:white;border:1px solid #dcecf5;border-radius:18px}.ca50-empty>i{font-size:32px;color:var(--ca-blue)}.ca50-empty h2{font-size:22px}.ca50-empty p{font-size:14px;line-height:1.8;color:#60788a}
.ca50-inner-pagination{display:flex;justify-content:center;align-items:center;gap:22px;margin-top:32px;font-size:13px}.ca50-inner-pagination a{padding:12px 18px;border:1px solid #cfe2ed;border-radius:10px;background:#fff;color:var(--ca-deep)}
.ca50-editorial{padding:36px;background:#fff;border:1px solid #dcecf5;border-radius:22px}.ca50-editorial-cover{width:100%;max-height:440px;object-fit:contain;background:#f1f8fc;border-radius:16px;margin-bottom:30px}.ca50-editorial-body{max-width:900px;margin:auto;font-size:16px;line-height:1.95;overflow-wrap:anywhere;overflow-x:auto}.ca50-editorial-body h2{font-size:25px;line-height:1.5;margin-top:32px}.ca50-editorial-body img{max-width:100%;height:auto;border-radius:12px}.ca50-editorial-body table{width:100%;border-collapse:collapse}.ca50-editorial-body td,.ca50-editorial-body th{padding:12px;border:1px solid #dcecf5}.ca50-editorial-body a{color:var(--ca-deep);text-decoration:underline}
.ca50-inner-cta{display:flex;align-items:center;justify-content:space-between;gap:28px;margin-top:32px;padding:30px;border-radius:20px;background:#e4f4ff}.ca50-inner-cta h2{font-size:22px;line-height:1.5;margin:0 0 10px}.ca50-inner-cta p{font-size:14px;line-height:1.8;margin:0;color:#60788a}.ca50-inner-page :focus-visible{outline:3px solid var(--ca-orange);outline-offset:3px}
@media(max-width:1000px){.ca50-catalog-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.ca50-catalog-grid,.ca50-service-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.ca50-inner-container{width:calc(100% - 32px)}.ca50-inner-heading h1{font-size:28px}.ca50-catalog-filters{grid-template-columns:1fr;padding:20px}.ca50-catalog-grid{gap:12px}.ca50-inner-page .ca50-product-image{height:165px}.ca50-inner-page .ca50-product-card>div{padding:12px}.ca50-inner-page .ca50-product-card h3{font-size:13px}.ca50-inner-page .ca50-product-card strong{font-size:15px}.ca50-service-grid{grid-template-columns:1fr}.ca50-editorial{padding:22px}.ca50-editorial-body{font-size:14px}.ca50-editorial-body h2{font-size:22px}.ca50-inner-cta{flex-direction:column;align-items:flex-start;padding:24px}.ca50-inner-cta h2{font-size:21px}.ca50-inner-page{padding-bottom:32px}}
</style>
